package vn.edu.eaut.lab9.repository;
import jakarta.persistence.*;import vn.edu.eaut.lab9.config.JPAUtil;import java.util.*;
public abstract class BaseRepository<T,ID>{protected abstract Class<T> type(); public List<T> findAll(){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();try{return e.createQuery("from "+type().getSimpleName(),type()).getResultList();}finally{e.close();}} public T findById(ID id){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();try{return e.find(type(),id);}finally{e.close();}} public void save(T x){tx(e->e.persist(x));} public T update(T x){final Object[] r=new Object[1];tx(e->r[0]=e.merge(x));return type().cast(r[0]);} public void delete(ID id){tx(e->{T x=e.find(type(),id);if(x!=null)e.remove(x);});} protected void tx(java.util.function.Consumer<EntityManager> c){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();EntityTransaction t=e.getTransaction();try{t.begin();c.accept(e);t.commit();}catch(RuntimeException ex){if(t.isActive())t.rollback();throw ex;}finally{e.close();}}}
